uniform vec3 uGrid;uniform vec3 uSize;uniform vec2 uAtlas;uniform float uTiles;
vec3 cell(){vec2 t=floor(gl_FragCoord.xy/uGrid.xy);return vec3(mod(gl_FragCoord.xy,uGrid.xy)-.5,t.x+t.y*uTiles);}
vec2 atlas(vec3 p){p=clamp(p,vec3(0),uGrid-1.);return (vec2(mod(p.z,uTiles),floor(p.z/uTiles))*uGrid.xy+p.xy+.5)/uAtlas;}
vec4 at(sampler2D t,vec3 p){return texture(t,atlas(p));}
vec4 sampleV(sampler2D t,vec3 p){p=clamp(p,vec3(0),uGrid-1.001);float z=floor(p.z);return mix(texture(t,atlas(vec3(p.xy,z))),texture(t,atlas(vec3(p.xy,z+1.))),fract(p.z));}
vec3 world(vec3 p){return (p+.5)/uGrid*uSize-vec3(uSize.x*.5,0.,uSize.z*.5);}
const vec3 X=vec3(1,0,0),Y=vec3(0,1,0),Z=vec3(0,0,1);
uniform int uScene,uObstacle;uniform float uIgnition,uOxygen,uRadius,uBurst;
float solid(vec3 p){vec3 w=world(p);if(p.y<0.)return 1.;if(uObstacle==1)return 1.-step(.50,length(w-vec3(0,1.28,0)));if(uObstacle==2)return 1.-step(0.,max(abs(w.y-1.3)-.075,max(abs(w.x)-.72,abs(w.z)-.60)));if(uObstacle==3)return (1.-step(.55,length(w.xz)))*(1.-step(.045,abs(w.y-.62)));return 0.;}
float faceOpen(vec3 p,vec3 d){return (1.-solid(p))*(1.-solid(p+d));}

vec3 macVelocity(sampler2D t,vec3 p){
 return vec3(sampleV(t,p-.5*X).x,sampleV(t,p-.5*Y).y,sampleV(t,p-.5*Z).z);
}
vec3 centeredVelocity(sampler2D t,vec3 p){
 return .5*vec3(at(t,p).x+at(t,p-X).x,at(t,p).y+at(t,p-Y).y,at(t,p).z+at(t,p-Z).z);
}
vec3 traceMAC(sampler2D t,vec3 p,float dt){
 vec3 mid=p-.5*dt*macVelocity(t,p)*uGrid/uSize;
 vec3 dep=p-dt*macVelocity(t,mid)*uGrid/uSize;
 // A blocked characteristic falls back to its fluid-side position. This is
 // deliberately dissipative near walls, rather than correcting through solids.
 if(uObstacle>0){for(int k=1;k<=4;k++)if(solid(mix(p,dep,float(k)*.25))>.5)return p;}
 if(dep.y<-.49)dep.y=-.49;
 return dep;
}

uniform int uEmitter,uWindMode;
uniform vec4 uReactionParams,uSourceParams;
uniform vec3 uWindVector,uDirection,uTint;
uniform float uSourceHeight,uWindFrequency,uSwirl,uBuoyancy,uCooling,uColorMix,uChemilum,uPulseDuration;
float pySegment(vec2 p,vec2 a,vec2 b){vec2 d=b-a;return length(p-a-d*clamp(dot(p-a,d)/max(dot(d,d),1e-8),0.,1.));}
float pyDisk(vec2 q,float r){return 1.-smoothstep(r*.65,r,length(q));}
float pyPortRing(vec2 q,float r){
 float a=atan(q.y,q.x),n=20.;a=floor((a+3.14159265)*n/6.2831853+.5)*6.2831853/n-3.14159265;
 vec2 c=r*vec2(cos(a),sin(a));float aa=.55*max(uSize.x/uGrid.x,uSize.z/uGrid.z);return 1.-smoothstep(max(.001,.028-aa),.028+aa,length(q-c));
}
float pySource(vec3 w,float time){
 float s=0.,h=uSourceHeight,dy=max(.028,.65*uSize.y/uGrid.y);
 float layer=exp(-pow((w.y-h)/dy,2.));
 if(uEmitter==0){for(int i=0;i<5;i++){
  float fi=float(i),ang=fi*1.91+.2,y=.24+mod(fi,2.)*.065;
  vec2 a=vec2(cos(ang)*.72,sin(ang)*.51),b=vec2(cos(ang+2.8)*.72,sin(ang+2.8)*.51);
  float r=.080+mod(fi,2.)*.016;
  s=max(s,(1.-smoothstep(r*.50,r+.032,pySegment(w.xz,a,b)))*exp(-pow((w.y-y-r*.8)/max(.045,dy),2.)));
 }}
 else if(uEmitter==1||uEmitter==3||uEmitter==14)s=pyDisk(w.xz,uRadius)*layer;
 else if(uEmitter==2||uEmitter==11)s=pyDisk(vec2(length(w-vec3(0,h,0)),0),uRadius)*uBurst;
 else if(uEmitter==4){vec3 e=vec3(.80*sin(time*1.1),h,.58*cos(time*.8));s=1.-smoothstep(.09,.18,length(w-e));}
 else if(uEmitter==5)s=pyDisk(w.xz,uRadius)*layer;
 else if(uEmitter==6)s=pyPortRing(w.xz,uRadius)*layer;
 else if(uEmitter==7){for(int i=0;i<4;i++){vec2 c=vec2((i%2)==0?-.64:.64,i<2?-.57:.57);s=max(s,pyPortRing(w.xz-c,uRadius)*layer);}}
 else if(uEmitter==8){vec3 q=w-vec3(0,h,0),d=normalize(uDirection);float along=dot(q,d);s=pyDisk(vec2(length(q-d*along),0),uRadius)*exp(-pow(along/max(.05,dy),2.));}
 else if(uEmitter==9){for(int i=0;i<5;i++){vec2 q=w.xz-vec2((float(i)-2.)*.43,0);s=max(s,pyDisk(q,uRadius)*layer);}}
 else if(uEmitter==10){for(int i=0;i<2;i++){vec3 q=w-vec3(i==0?-.88:.88,h,0);s=max(s,pyDisk(q.yz,uRadius)*exp(-pow(q.x/max(.055,dy),2.)));}}
 else if(uEmitter==12)s=(1.-smoothstep(.70,.85,abs(w.x)))*(1.-smoothstep(.025,.065,abs(w.z)))*layer;
 else if(uEmitter==13){for(int i=0;i<3;i++){vec3 q=w-vec3((float(i)-1.)*.55,h,0);s=max(s,pyDisk(q.xz,uRadius)*layer);}}
 if(uEmitter==14)s*=smoothstep(.4,.6,sin(time*6.2831853*1.5));
 if(uWindMode==5)s*=.45+.55*(.5+.5*sin(3.*atan(w.z,w.x)-time*3.));
 return max(0.,s);
}
vec3 pyVelocity(vec3 w,float time){
 vec3 d=normalize(uDirection);float sp=uSourceParams.z;
 vec3 v=d*sp;
 if(uEmitter==0)v=vec3(.45*sin(w.z*19.+time*5.2),sp,.4*cos(w.x*17.-time*4.7));
 if(uEmitter==2){vec3 q=w-vec3(0,uSourceHeight,0);v=normalize(q+vec3(1e-6))*sp+vec3(0,.5,0);}
 if(uEmitter==11){vec3 q=w-vec3(0,uSourceHeight,0);v=normalize(q+vec3(1e-6))*sp+vec3(0,1.0,0);}
 if(uEmitter==10)v=vec3(w.x<0.?sp:-sp,.4,0);
 return v;
}
vec3 pyWind(vec3 w,float time,vec3 v){
 vec3 a=uWindVector;float f=time*uWindFrequency*6.2831853;
 if(uWindMode==1)a*=.35+.65*(.5+.5*sin(f));
 if(uWindMode==2)a*=sin(f);
 if(uWindMode==3){float m=length(a);a=vec3(cos(f),0,sin(f))*m;}
 if(uWindMode==4)a*=clamp((w.y-.25)*.8,-.2,2.);
 if(uWindMode==5){float r2=dot(w.xz,w.xz);vec2 tangent=vec2(-w.z,w.x);
  vec2 target=uSwirl*tangent/(r2+.16)-w.xz*.23;
  a+=vec3(target.x-v.x,.12*exp(-r2/.7),target.y-v.z)*1.8;
 }
 return a;
}
void pyReact(inout vec4 O,inout vec4 C,float injection,float dt){
 // Normalized finite-rate surrogate, shared byte-for-byte across macro / refined.
 if(uEmitter==3){C.z+=dt*2.8*injection;O.w+=dt*.90*injection;}
 else if(uEmitter==11){float w=1.-exp(-dt*8.*injection);O.w=mix(O.w,1.85,w);C.z=mix(C.z,.85,w);}
 else {
  C.x+=dt*uSourceParams.x*injection;
  O.w+=max(0.,.42-O.w)*(1.-exp(-dt*16.*injection))*uIgnition;
  C.y+=(uOxygen*uSourceParams.y-C.y)*(1.-exp(-dt*3.*injection));
 }
 float st=uReactionParams.w;
 float available=min(max(C.x,0.),max(C.y,0.)/max(st,.1));
 float burn=available*(1.-exp(-uReactionParams.x*dt))*smoothstep(.12,.29,O.w);
 C.x-=burn;C.y-=st*burn;C.z+=uReactionParams.z*burn;C.w=burn/max(dt,1e-6);O.w+=burn*uReactionParams.y;
 O.w*=exp(-dt*uCooling*(.26+.27*O.w*O.w));
 C.z*=exp(-dt*(.025+.09*O.w*max(C.y,0.)));C.x*=exp(-dt*.012);
 C=max(C,vec4(0));O.w=max(O.w,0.);
}
vec3 pyEmission(float heat,vec4 c,vec3 B){
 vec3 thermal=B*c.z*9.;
 float lum=dot(thermal,vec3(.2126,.7152,.0722));
 thermal=mix(thermal,lum*uTint/max(dot(uTint,vec3(.2126,.7152,.0722)),.10),uColorMix);
 vec3 chem=uTint*uChemilum*max(c.w,0.)*smoothstep(.13,.45,heat);
 return thermal+chem;
}
